# Fixes the Nav-in-client-component build error: splits checkout/success
# into a Server Component page (renders Nav/Footer) and a Client
# Component holding just the interactive download-polling logic.

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\checkout\success\CheckoutSuccessClient.tsx"), $bytes)
Write-Host "WRITTEN: src\app\checkout\success\CheckoutSuccessClient.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\checkout\success\page.tsx"), $bytes)
Write-Host "WRITTEN: src\app\checkout\success\page.tsx" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan